func (m Model) renderTableView() string {
	var b strings.Builder

	// Table header
	tableHeaderStyle := lipgloss.NewStyle().
		Bold(true).
		Foreground(lipgloss.Color("39")).
		BorderStyle(lipgloss.NormalBorder()).
		BorderBottom(true).
		BorderForeground(lipgloss.Color("240"))

	// Column widths
	idW := 4
	timeW := 10
	methodW := 8
	pathW := 20
	bodyW := 40

	header := fmt.Sprintf("%-*s %-*s %-*s %-*s %-*s",
		idW, "ID",
		timeW, "Time",
		methodW, "Method",
		pathW, "Path",
		bodyW, "Body Preview",
	)
	b.WriteString(tableHeaderStyle.Render(header) + "\n")

	// Table rows
	maxShow := 15
	if len(m.webhooks) < maxShow {
		maxShow = len(m.webhooks)
	}

	for i := 0; i < maxShow; i++ {
		wh := m.webhooks[i]
		preview := truncate(wh.Body, bodyW-3)
		if preview == "" {
			preview = "(empty)"
		}
		path := truncate(wh.Path, pathW-3)

		row := fmt.Sprintf("%-*d %-*s %-*s %-*s %-*s",
			idW, wh.ID,
			timeW, wh.Timestamp.Format("15:04:05"),
			methodW, wh.Method,
			pathW, path,
			bodyW, preview,
		)

		if i == m.selectedIdx {
			rowStyle := lipgloss.NewStyle().
				Background(lipgloss.Color("236")).
				Foreground(lipgloss.Color("212"))
			b.WriteString(rowStyle.Render(row) + "\n")
		} else {
			// Color-code method in row
			methodColored := methodStyle(wh.Method)
			row = fmt.Sprintf("%-*d %-*s %s%s %-*s %-*s",
				idW, wh.ID,
				timeW, wh.Timestamp.Format("15:04:05"),
				methodColored, strings.Repeat(" ", methodW-len(wh.Method)),
				pathW, path,
				bodyW, preview,
			)
			b.WriteString(row + "\n")
		}
	}

	return b.String()
}

