		timeW, "Time",
		methodW, "Method",
		pathW, "Path",
		bodyW, "Body Preview",
	)
	b.WriteString(tableHeaderStyle.Render(header) + "\n")

	// Table rows
	maxShow := 15
	if len(m.webhooks) < maxShow {
		maxShow = len(m.webhooks)
	}

	for i := 0; i < maxShow; i++ {
